      - {name: "物品总成本",  field_index: 12, type: formula,      format: "0.00",
          formula: "=J{row}*K{row}"}
      # 按 market 描述：单品单份总成本 = M 列 BOM 加和
      - {name: "单品单份总成本", field_index: 13, type: block_formula, format: "0.00", merge: true,
          formula: "=SUM(M{block_start}:M{block_end})"}
      # 单品毛利 = 单价(E) - 单品单份总成本(N)
      - {name: "单品毛利",    field_index: 14, type: block_formula, format: "0.00", merge: true, negative_red: true,
          formula: "=E{block_start}-N{block_start}"}
      # 总毛利 = 销量(D) × 单品毛利(O) = 销售数量 × 单品毛利（按 market 要求硬算）
      - {name: "总毛利",      field_index: 15, type: block_formula, format: "0.00", merge: true, negative_red: true,
          formula: "=D{block_start}*O{block_start}"}
      - {name: "毛利率",      field_index: 16, type: block_formula, format: "0.00%", merge: true, negative_red: true,
          formula: "=IF(G{block_start}=0,0,P{block_start}/G{block_start})"}
